import React, { useState } from 'react';
import { Project, Staff, ProjectCategory } from '../types';
import { GoogleGenAI, Type } from "@google/genai";

interface AdminDashboardProps {
  projects: Project[];
  staff: Staff[];
  onUpdateProjects: (projects: Project[]) => void;
  onUpdateStaff: (staff: Staff[]) => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ projects, staff, onUpdateProjects, onUpdateStaff }) => {
  const [activeTab, setActiveTab] = useState<'projects' | 'staff'>('projects');
  const [isEditing, setIsEditing] = useState(false);
  const [editProject, setEditProject] = useState<Partial<Project>>({});
  const [editStaff, setEditStaff] = useState<Partial<Staff>>({});
  const [isGenerating, setIsGenerating] = useState(false);

  const generateAIDescription = async () => {
    if (!editProject.title) return alert("Enter a title first");
    setIsGenerating(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Write a compelling, short cinematic description for a film titled "${editProject.title}" where the director role is "${editProject.role || 'Director'}". Category is ${editProject.category || 'Film'}. Keep it under 200 characters.`,
      });
      setEditProject({ ...editProject, description: response.text?.trim() });
    } catch (err) {
      console.error(err);
      alert("AI generation failed. Check console.");
    } finally {
      setIsGenerating(false);
    }
  };

  const handleSaveProject = (e: React.FormEvent) => {
    e.preventDefault();
    if (editProject.id) {
      onUpdateProjects(projects.map(p => p.id === editProject.id ? editProject as Project : p));
    } else {
      const newProject = { ...editProject, id: Date.now().toString() } as Project;
      onUpdateProjects([...projects, newProject]);
    }
    setEditProject({});
    setIsEditing(false);
  };

  const handleDeleteProject = (id: string) => {
    if (window.confirm("Delete this project?")) {
      onUpdateProjects(projects.filter(p => p.id !== id));
    }
  };

  const handleSaveStaff = (e: React.FormEvent) => {
    e.preventDefault();
    if (editStaff.id) {
      onUpdateStaff(staff.map(s => s.id === editStaff.id ? editStaff as Staff : s));
    } else {
      const newStaffMember = { ...editStaff, id: Date.now().toString() } as Staff;
      onUpdateStaff([...staff, newStaffMember]);
    }
    setEditStaff({});
    setIsEditing(false);
  };

  const handleDeleteStaff = (id: string) => {
    if (window.confirm("Delete this staff member?")) {
      onUpdateStaff(staff.filter(s => s.id !== id));
    }
  };

  return (
    <div className="pt-24 min-h-screen max-w-7xl mx-auto px-6 pb-24">
      <header className="flex flex-col md:flex-row justify-between items-center py-12 gap-6">
        <div>
          <h1 className="text-3xl font-serif text-white tracking-widest uppercase">Content Management</h1>
          <p className="text-neutral-500 mt-2">Manage your filmography and team members.</p>
        </div>
        <div className="flex bg-neutral-900 rounded-lg p-1">
          <button 
            onClick={() => setActiveTab('projects')}
            className={`px-6 py-2 rounded-md transition-all ${activeTab === 'projects' ? 'bg-yellow-500 text-black' : 'text-neutral-400'}`}
          >
            Projects
          </button>
          <button 
            onClick={() => setActiveTab('staff')}
            className={`px-6 py-2 rounded-md transition-all ${activeTab === 'staff' ? 'bg-yellow-500 text-black' : 'text-neutral-400'}`}
          >
            Staff
          </button>
        </div>
      </header>

      {/* Main Content Area */}
      {isEditing ? (
        <div className="bg-neutral-900 p-8 rounded-xl border border-white/5 animate-in fade-in slide-in-from-bottom-4">
          <h2 className="text-2xl font-serif mb-8 text-white">
            {activeTab === 'projects' ? (editProject.id ? 'Edit Project' : 'New Project') : (editStaff.id ? 'Edit Staff' : 'New Staff')}
          </h2>

          {activeTab === 'projects' ? (
            <form onSubmit={handleSaveProject} className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-4">
                <label className="block">
                  <span className="text-xs uppercase tracking-widest text-neutral-500">Title</span>
                  <input 
                    type="text" 
                    value={editProject.title || ''}
                    onChange={(e) => setEditProject({...editProject, title: e.target.value})}
                    className="mt-1 block w-full bg-black border border-neutral-800 rounded-md p-3 text-white focus:border-yellow-500 outline-none"
                    required
                  />
                </label>
                <div className="grid grid-cols-2 gap-4">
                  <label className="block">
                    <span className="text-xs uppercase tracking-widest text-neutral-500">Year</span>
                    <input 
                      type="text" 
                      value={editProject.year || ''}
                      onChange={(e) => setEditProject({...editProject, year: e.target.value})}
                      className="mt-1 block w-full bg-black border border-neutral-800 rounded-md p-3 text-white focus:border-yellow-500 outline-none"
                    />
                  </label>
                  <label className="block">
                    <span className="text-xs uppercase tracking-widest text-neutral-500">Category</span>
                    <select 
                      value={editProject.category || ProjectCategory.FILM}
                      onChange={(e) => setEditProject({...editProject, category: e.target.value as ProjectCategory})}
                      className="mt-1 block w-full bg-black border border-neutral-800 rounded-md p-3 text-white focus:border-yellow-500 outline-none"
                    >
                      {Object.values(ProjectCategory).map(cat => <option key={cat} value={cat}>{cat}</option>)}
                    </select>
                  </label>
                </div>
                <label className="block">
                  <span className="text-xs uppercase tracking-widest text-neutral-500">Role</span>
                  <input 
                    type="text" 
                    value={editProject.role || ''}
                    onChange={(e) => setEditProject({...editProject, role: e.target.value})}
                    className="mt-1 block w-full bg-black border border-neutral-800 rounded-md p-3 text-white focus:border-yellow-500 outline-none"
                  />
                </label>
                <label className="block">
                  <span className="text-xs uppercase tracking-widest text-neutral-500">Poster URL (G-Drive or Direct)</span>
                  <input 
                    type="text" 
                    value={editProject.posterUrl || ''}
                    onChange={(e) => setEditProject({...editProject, posterUrl: e.target.value})}
                    placeholder="https://..."
                    className="mt-1 block w-full bg-black border border-neutral-800 rounded-md p-3 text-white focus:border-yellow-500 outline-none"
                  />
                </label>
              </div>
              <div className="space-y-4">
                <label className="block">
                  <div className="flex justify-between items-center mb-1">
                    <span className="text-xs uppercase tracking-widest text-neutral-500">Description</span>
                    <button 
                      type="button"
                      onClick={generateAIDescription}
                      disabled={isGenerating}
                      className="text-[10px] text-yellow-500 hover:text-white uppercase font-bold flex items-center gap-1 transition-colors disabled:opacity-50"
                    >
                      <i className={`fas ${isGenerating ? 'fa-spinner fa-spin' : 'fa-wand-magic-sparkles'}`}></i>
                      AI Generate
                    </button>
                  </div>
                  <textarea 
                    rows={4}
                    value={editProject.description || ''}
                    onChange={(e) => setEditProject({...editProject, description: e.target.value})}
                    className="mt-1 block w-full bg-black border border-neutral-800 rounded-md p-3 text-white focus:border-yellow-500 outline-none resize-none"
                  ></textarea>
                </label>
                <label className="block">
                  <span className="text-xs uppercase tracking-widest text-neutral-500">Still Images (Comma separated URLs)</span>
                  <textarea 
                    rows={3}
                    value={editProject.stillUrls?.join(', ') || ''}
                    onChange={(e) => setEditProject({...editProject, stillUrls: e.target.value.split(',').map(s => s.trim()).filter(s => s !== '')})}
                    placeholder="url1, url2, ..."
