interface AdminDashboardProps {
  projects: Project[];
  staff: Staff[];
  onUpdateProjects: (projects: Project[]) => void;
  onUpdateStaff: (staff: Staff[]) => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ projects, staff, onUpdateProjects, onUpdateStaff }) => {
  const [activeTab, setActiveTab] = useState<'projects' | 'staff'>('projects');
  const [isEditing, setIsEditing] = useState(false);
  const [editProject, setEditProject] = useState<Partial<Project>>({});
  const [editStaff, setEditStaff] = useState<Partial<Staff>>({});
  const [isGenerating, setIsGenerating] = useState(false);

  const generateAIDescription = async () => {
    if (!editProject.title) return alert("Enter a title first");
    setIsGenerating(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Write a compelling, short cinematic description for a film titled "${editProject.title}" where the director role is "${editProject.role || 'Director'}". Category is ${editProject.category || 'Film'}. Keep it under 200 characters.`,
      });
      setEditProject({ ...editProject, description: response.text?.trim() });
    } catch (err) {
      console.error(err);
      alert("AI generation failed. Check console.");
    } finally {
      setIsGenerating(false);
    }
  };

  const handleSaveProject = (e: React.FormEvent) => {
    e.preventDefault();
    if (editProject.id) {
      onUpdateProjects(projects.map(p => p.id === editProject.id ? editProject as Project : p));
    } else {
      const newProject = { ...editProject, id: Date.now().toString() } as Project;
      onUpdateProjects([...projects, newProject]);
    }
    setEditProject({});
    setIsEditing(false);
  };

  const handleDeleteProject = (id: string) => {
    if (window.confirm("Delete this project?")) {
      onUpdateProjects(projects.filter(p => p.id !== id));
    }
  };

  const handleSaveStaff = (e: React.FormEvent) => {
    e.preventDefault();
    if (editStaff.id) {
      onUpdateStaff(staff.map(s => s.id === editStaff.id ? editStaff as Staff : s));
    } else {
      const newStaffMember = { ...editStaff, id: Date.now().toString() } as Staff;
      onUpdateStaff([...staff, newStaffMember]);
    }
    setEditStaff({});
    setIsEditing(false);
  };

  const handleDeleteStaff = (id: string) => {
    if (window.confirm("Delete this staff member?")) {
      onUpdateStaff(staff.filter(s => s.id !== id));
    }
  };

