            Staff
          </button>
        </div>
      </header>

      {/* Main Content Area */}
      {isEditing ? (
        <div className="bg-neutral-900 p-8 rounded-xl border border-white/5 animate-in fade-in slide-in-from-bottom-4">
          <h2 className="text-2xl font-serif mb-8 text-white">
