                  <div className="flex gap-4">
                    <button onClick={() => { setEditProject(p); setIsEditing(true); }} className="text-neutral-400 hover:text-yellow-500 p-2 transition-colors">
                      <i className="fas fa-edit"></i>
                    </button>
                    <button onClick={() => handleDeleteProject(p.id)} className="text-neutral-400 hover:text-red-500 p-2 transition-colors">
                      <i className="fas fa-trash"></i>
                    </button>
                  </div>
                </div>
              ))
            ) : (
              staff.map(s => (
                <div key={s.id} className="bg-neutral-900/50 p-6 rounded-lg border border-white/5 flex items-center justify-between group">
                  <div className="flex items-center gap-6">
                    <img src={formatImageUrl(s.photoUrl)} className="w-12 h-12 rounded-full object-cover shadow-lg" alt="" />
                    <div>
                      <h4 className="text-white font-serif text-lg">{s.name}</h4>
                      <p className="text-neutral-500 text-xs uppercase tracking-widest">{s.role}</p>
                    </div>
                  </div>
                  <div className="flex gap-4">
                    <button onClick={() => { setEditStaff(s); setIsEditing(true); }} className="text-neutral-400 hover:text-yellow-500 p-2 transition-colors">
                      <i className="fas fa-edit"></i>
                    </button>
                    <button onClick={() => handleDeleteStaff(s.id)} className="text-neutral-400 hover:text-red-500 p-2 transition-colors">
                      <i className="fas fa-trash"></i>
                    </button>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminDashboard;

export enum ProjectCategory {
