interface AdminDashboardProps {
  projects: Project[];
  staff: Staff[];
  director: DirectorInfo;
  onUpdateProjects: (projects: Project[]) => void;
  onUpdateStaff: (staff: Staff[]) => void;
  onUpdateDirector: (info: DirectorInfo) => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
  projects, 
  staff, 
  director,
  onUpdateProjects, 
  onUpdateStaff,
  onUpdateDirector
}) => {
  const [activeTab, setActiveTab] = useState<'projects' | 'staff' | 'director' | 'export'>('projects');
  const [isEditing, setIsEditing] = useState(false);
  const [editProject, setEditProject] = useState<Partial<Project>>({});
  const [editStaff, setEditStaff] = useState<Partial<Staff>>({});
  const [editDirector, setEditDirector] = useState<DirectorInfo>(director);
  const [isGenerating, setIsGenerating] = useState(false);

  // Added handleSaveProject to fix the error: Cannot find name 'handleSaveProject'
  const handleSaveProject = (e: React.FormEvent) => {
    e.preventDefault();
    if (editProject.id) {
      // Update existing project
      const updated = projects.map(p => p.id === editProject.id ? { ...p, ...editProject } as Project : p);
      onUpdateProjects(updated);
    } else {
      // Add new project
      const newProject: Project = {
        ...editProject,
        id: Date.now().toString(),
        category: editProject.category || ProjectCategory.FILM,
        title: editProject.title || '',
        year: editProject.year || '',
        role: editProject.role || '',
        description: editProject.description || '',
        posterUrl: editProject.posterUrl || '',
        stillUrls: editProject.stillUrls || []
      } as Project;
      onUpdateProjects([...projects, newProject]);
    }
    setIsEditing(false);
    setEditProject({});
  };

  // Added handleSaveStaff to fix the error: Cannot find name 'handleSaveStaff'
  const handleSaveStaff = (e: React.FormEvent) => {
    e.preventDefault();
    if (editStaff.id) {
      // Update existing staff member
      const updated = staff.map(s => s.id === editStaff.id ? { ...s, ...editStaff } as Staff : s);
      onUpdateStaff(updated);
    } else {
      // Add new staff member
      const newMember: Staff = {
        ...editStaff,
        id: Date.now().toString(),
