interface ProjectListProps {
  category: ProjectCategory;
  projects: Project[];
}

const ProjectList: React.FC<ProjectListProps> = ({ category, projects }) => {
  const filteredProjects = projects.filter(p => p.category === category);

  // 연도별로 그룹화
  const groupedByYear = filteredProjects.reduce((acc: { [key: string]: Project[] }, project) => {
    if (!acc[project.year]) acc[project.year] = [];
    acc[project.year].push(project);
    return acc;
  }, {});

  const sortedYears = Object.keys(groupedByYear).sort((a, b) => b.localeCompare(a));

  return (
    <div className="pt-32 min-h-screen bg-black text-neutral-300">
      <div className="max-w-4xl mx-auto px-8 py-20">
        {/* Header Style from Image */}
        <header className="mb-24 border-b border-white/5 pb-10">
          <h1 className="text-2xl md:text-3xl font-serif text-white tracking-[0.2em] uppercase">
            {category}
          </h1>
        </header>

        <div className="space-y-24">
          {sortedYears.map((year) => (
            <div key={year} className="flex flex-col md:flex-row gap-8 md:gap-24">
              {/* Year Column */}
              <div className="w-full md:w-32 flex-shrink-0">
                <span className="text-2xl font-bold text-yellow-600 font-sans tracking-tight">
                  {year}
                </span>
              </div>

              {/* Works Column */}
              <div className="flex-grow space-y-12">
                {groupedByYear[year].map((project) => (
                  <div key={project.id} className="space-y-3">
                    <h3 className="text-white text-lg font-bold group flex items-center">
                      <span className={project.isFeature ? "text-orange-400" : ""}>
                        {project.title}
                      </span>
                      <span className="ml-3 text-neutral-200 font-bold tracking-tight">
                        {project.role}
                      </span>
                      {project.link && (
                        <a 
                          href={project.link} 
                          target="_blank" 
                          rel="noreferrer" 
                          className="ml-4 text-neutral-600 hover:text-yellow-500 transition-colors text-sm"
                        >
                          <i className="fas fa-external-link-alt"></i>
                        </a>
                      )}
                    </h3>

                    {project.awardsList && project.awardsList.length > 0 && (
                      <ul className="space-y-1 ml-4 border-l border-white/10 pl-4">
                        {project.awardsList.map((award, idx) => (
                          <li key={idx} className="text-neutral-500 text-sm font-light flex items-center before:content-['•'] before:mr-2 before:text-neutral-700">
                            {award}
                          </li>
                        ))}
                      </ul>
                    )}

                    {project.description && (
                      <p className="text-neutral-500 text-sm font-light italic ml-4">
                        {project.description}
                      </p>
                    )}
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>

        {filteredProjects.length === 0 && (
          <div className="py-40 text-center text-neutral-600 italic">
            No works registered in this category.
          </div>
        )}
      </div>
    </div>
  );
};

