          </div>
        </div>
      </section>

      {/* CV Section */}
      <section id="filmography" className="py-24 md:py-48 px-6 max-w-6xl mx-auto border-t border-white/5">
        <header className="mb-24 md:mb-40 text-center space-y-6 md:space-y-10">
