                    <span className="text-yellow-600 font-bold tracking-widest text-xs md:text-sm block">
                      {project.year}
                    </span>
                    <h2 
                      className="text-3xl md:text-5xl font-serif text-white leading-tight tracking-tight break-keep cursor-pointer hover:text-yellow-500 transition-colors"
