                  {[
                    { label: 'Year', value: selectedProject.year },
                    { label: 'Genre', value: formatText(selectedProject.genre) || 'Drama' },
                    { label: 'Runtime', value: formatText(selectedProject.runtime) || 'N/a' },
                    { label: 'Role', value: selectedProject.role }
