import { DIRECTOR_INFO } from '../data';
import { formatImageUrl } from '../utils/imageHelper';

interface ProjectListProps {
  category: ProjectCategory;
  projects: Project[];
}

const ProjectList: React.FC<ProjectListProps> = ({ category, projects }) => {
  const [selectedProject, setSelectedProject] = useState<Project | null>(null);
  const filteredProjects = projects.filter(p => p.category === category);

  // 데이터에 정의된 순서 그대로 유지
  const displayProjects = filteredProjects; 

  const isCommercial = category === ProjectCategory.COMMERCIAL;
  const isProducing = category === ProjectCategory.PRODUCING;

  // 첫 글자만 대문자, 나머지는 소문자로 변환하는 헬퍼 함수
  const formatText = (str: string | undefined) => {
    if (!str) return '';
    return str.charAt(0).toUpperCase() + str.slice(1).toLowerCase();
  };

  const handleProjectClick = (project: Project) => {
    if (isCommercial) {
      window.open(project.link || DIRECTOR_INFO.adPortfolio, '_blank');
    } else {
      setSelectedProject(project);
    }
  };

  return (
    <div className="pt-24 md:pt-32 min-h-screen bg-black text-neutral-300 overflow-x-hidden">
      <div className="max-w-7xl mx-auto px-6 py-12 md:py-20">
        <header className="mb-24 md:mb-40 text-center">
          <h1 className="text-4xl sm:text-6xl md:text-8xl font-serif text-white tracking-[0.1em] md:tracking-[0.2em] uppercase mb-4 leading-tight">
            {category}
          </h1>
          <div className="w-16 md:w-24 h-px bg-white/20 mx-auto mt-6 md:mt-10"></div>
        </header>

        <div className="space-y-40 md:space-y-64">
          {displayProjects.map((project, index) => {
            const isEven = index % 2 === 0;
            const hasPoster = !isProducing && project.posterUrl;

            return (
              <div 
                key={project.id} 
                className={`flex flex-col ${isEven ? 'md:flex-row' : 'md:flex-row-reverse'} items-center gap-10 md:gap-24`}
              >
                {/* 리스트 프리뷰 섹션 (포스터) */}
                <div 
                  className="w-full md:w-1/2 relative group cursor-pointer"
                  onClick={() => handleProjectClick(project)}
                >
                  <div className="aspect-[3/4.5] overflow-hidden bg-neutral-900 shadow-[0_0_50px_rgba(0,0,0,0.8)] border border-white/5 relative flex items-center justify-center">
                    {hasPoster ? (
                      <img 
                        src={formatImageUrl(project.posterUrl!)} 
                        alt={project.title}
                        className="w-full h-full object-cover transition-all duration-1000 group-hover:scale-105 opacity-80 group-hover:opacity-100"
                      />
                    ) : (
                      <div className="text-neutral-800 font-serif italic text-sm md:text-lg tracking-widest opacity-40 select-none">
                        NO POSTER AVAILABLE
                      </div>
                    )}

                    {project.isAI && (
                      <div className="absolute top-4 right-4 z-10">
                        <div className="bg-black/60 backdrop-blur-md border border-yellow-500/50 px-3 py-1 text-[9px] font-black tracking-[0.2em] text-yellow-500 uppercase rounded-sm shadow-xl">
                          AI FILM
                        </div>
                      </div>
                    )}

                    <div className="absolute inset-0 bg-black/20 group-hover:bg-transparent transition-all duration-500"></div>

                    <div className="absolute inset-0 flex items-center justify-center opacity-100 md:opacity-0 md:group-hover:opacity-100 transition-opacity duration-500">
                      <div className="border border-white bg-black/40 backdrop-blur-md px-6 md:px-8 py-3 text-[9px] md:text-[10px] uppercase tracking-[0.2em] md:tracking-[0.3em] font-bold text-white group-hover:bg-white group-hover:text-black transition-all flex items-center justify-center">
                        자세히 보기 {isCommercial && <i className="fab fa-youtube ml-3 text-red-500"></i>}
                      </div>
                    </div>
                  </div>
                </div>

                {/* 리스트 텍스트 섹션 (제목) */}
                <div className="w-full md:w-1/2 space-y-6 md:space-y-8 text-left">
                  <div className="space-y-3 md:space-y-4">
                    <span className="text-yellow-600 font-bold tracking-widest text-xs md:text-sm block">
                      {project.year}
                    </span>
                    <h2 
                      className="text-3xl md:text-5xl font-serif text-white leading-tight tracking-tight break-keep cursor-pointer hover:text-yellow-500 transition-colors"
                      onClick={() => handleProjectClick(project)}
                    >
                      {project.title} {project.titleEn && <span className="text-neutral-500 text-xl md:text-3xl block md:inline md:ml-2">({project.titleEn})</span>}
                    </h2>

                    {(project.genre || project.runtime || project.aspectRatio) && (
                      <div className="flex flex-wrap gap-3 md:gap-4 text-orange-400 font-bold text-[10px] md:text-xs tracking-widest pt-1 md:pt-2">
                        {project.genre && <span>{formatText(project.genre)}</span>}
                        {project.runtime && <span className="text-neutral-800">|</span>}
                        {project.runtime && <span>{formatText(project.runtime)}</span>}
                        {project.aspectRatio && <span className="text-neutral-800">|</span>}
                        {project.aspectRatio && <span>{project.aspectRatio}</span>}
                      </div>
                    )}
                  </div>

                  {!isCommercial && (
                    <p className="text-neutral-400 leading-relaxed font-light text-base md:text-lg max-w-lg">
                      {project.synopsis ? project.synopsis.slice(0, 150) + '...' : project.description || "상세 정보가 준비 중입니다."}
                    </p>
                  )}

                  {project.awardsList && project.awardsList.length > 0 && (
                    <div className="space-y-2 md:space-y-3 pt-2 md:pt-4">
                      {project.awardsList.slice(0, 5).map((award, i) => (
                        <div key={i} className="flex items-start gap-3 text-yellow-500/80 text-xs md:text-sm font-medium leading-snug">
                          <i className="fas fa-award text-[10px] text-yellow-600/70 mt-1"></i>
                          <span>{award}</span>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* 영화 상세 정보 모달 */}
      {!isCommercial && selectedProject && (
        <div className="fixed inset-0 z-[100] bg-black overflow-y-auto custom-scrollbar flex flex-col items-center">
          {/* 닫기 버튼 */}
          <button 
            className="fixed top-8 right-8 md:top-12 md:right-12 z-[120] text-neutral-700 hover:text-white transition-all p-3 group" 
            onClick={() => setSelectedProject(null)}
          >
            <i className="fas fa-times text-2xl group-hover:rotate-90 transition-transform duration-300"></i>
          </button>

          {/* 메인 콘텐츠 컨테이너: 중앙 정렬 */}
          <div className="w-full max-w-7xl px-6 md:px-12 pt-24 md:pt-48 pb-24 mx-auto">

            {/* 상단 섹션: 포스터(Sticky) + 정보(Scroll) */}
            <div className="flex flex-col lg:flex-row gap-16 lg:gap-32 mb-48 relative items-start justify-center">

              {/* 좌측: 포스터 & 스펙 (스티키) */}
              <div className="w-full lg:w-[400px] flex-shrink-0 lg:sticky lg:top-32 h-fit space-y-10">
                <div className="aspect-[3/4.2] overflow-hidden bg-neutral-950 border border-white/5 shadow-2xl relative">
                  {selectedProject.posterUrl ? (
                    <img 
                      src={formatImageUrl(selectedProject.posterUrl)} 
                      className="w-full h-full object-cover"
                      alt={selectedProject.title}
                    />
                  ) : (
                    <div className="w-full h-full flex items-center justify-center text-neutral-800 text-[10px] tracking-[0.5em] uppercase italic opacity-30">Cinematic Archive</div>
                  )}
                </div>

                {/* 하단 스펙 테이블 */}
                <div className="border-t border-white/10">
                  {[
                    { label: 'Year', value: selectedProject.year },
                    { label: 'Genre', value: formatText(selectedProject.genre) || 'Drama' },
                    { label: 'Runtime', value: formatText(selectedProject.runtime) || 'N/a' },
                    { label: 'Role', value: selectedProject.role }
                  ].map((item, idx) => (
                    <div key={idx} className="flex justify-between items-center py-4 border-b border-white/5">
                      <span className="text-[9px] uppercase tracking-[0.2em] text-neutral-500 font-bold">{item.label}</span>
                      <span className="text-[12px] font-bold text-neutral-200 tracking-tight">{item.value}</span>
                    </div>
                  ))}
                </div>
              </div>

              {/* 우측: 텍스트 정보 */}
              <div className="flex-grow space-y-24 max-w-2xl">
                {/* 1. 타이틀 영역 */}
                <div className="space-y-4">
                  <h2 className="text-4xl md:text-5xl lg:text-7xl font-serif text-white tracking-tight leading-[1.1] uppercase break-keep">
                    {selectedProject.title}
                  </h2>
                  {selectedProject.titleEn && (
                    <p className="text-neutral-500 font-serif text-xl md:text-2xl italic opacity-40">
                      {selectedProject.titleEn}
                    </p>
                  )}
                </div>

                {/* 2. 시놉시스: 줄 간격(1.8) 유지하되 글자 크기(15px/17px) 하향 조정 */}
                <div className="space-y-8">
                  <div className="flex items-center gap-6">
                    <div className="w-10 h-px bg-yellow-600/40"></div>
                    <h3 className="text-[10px] uppercase tracking-[0.5em] text-yellow-600 font-black">Synopsis</h3>
                  </div>
                  <p className="text-neutral-300 text-[15px] md:text-[17px] leading-[1.8] tracking-normal font-normal break-keep whitespace-pre-line opacity-90">
                    {selectedProject.synopsis || "작품의 기록이 준비 중입니다."}
                  </p>
                </div>

                {/* 2.5. 기획의도 (Planning Intention): description 필드가 있는 경우 표시 */}
                {selectedProject.description && (
                  <div className="space-y-8">
                    <div className="flex items-center gap-6">
                      <div className="w-10 h-px bg-yellow-600/40"></div>
                      <h3 className="text-[10px] uppercase tracking-[0.5em] text-yellow-600 font-black">Planning Intention</h3>
                    </div>
                    <p className="text-white text-[15px] md:text-[17px] font-serif italic leading-[1.8] tracking-tight break-keep whitespace-pre-line opacity-100">
                      {selectedProject.description}
                    </p>
                  </div>
                )}

                {/* 3. 수상 내역 (Recognition) */}
                {selectedProject.awardsList && selectedProject.awardsList.length > 0 && (
                  <div className="space-y-10">
                    <div className="flex items-center gap-6">
                      <div className="w-10 h-px bg-yellow-600/40"></div>
                      <h3 className="text-[10px] uppercase tracking-[0.5em] text-yellow-600 font-black">Recognition</h3>
                    </div>
                    <ul className="space-y-5">
                      {selectedProject.awardsList.map((award, i) => (
                        <li key={i} className="flex items-start gap-5 text-yellow-500/80 text-base md:text-lg font-light group">
                          <span className="w-1.5 h-1.5 rounded-full bg-yellow-600/30 mt-2.5 group-hover:bg-yellow-600 transition-colors"></span>
                          <span className="group-hover:text-yellow-400 transition-colors duration-300 leading-snug">{award}</span>
                        </li>
                      ))}
                    </ul>
                  </div>
                )}
              </div>
            </div>

            {/* 하단 섹션: 스틸컷 */}
            <div className="space-y-16 border-t border-white/5 pt-40">
              <div className="flex flex-col items-center gap-10 mb-16">
                 <h3 className="text-[10px] uppercase tracking-[1em] text-neutral-700 font-black">Cinematic Frames</h3>
                 <div className="w-px h-24 bg-gradient-to-b from-white/10 to-transparent"></div>
              </div>

              <div className="space-y-16 md:space-y-32">
                {selectedProject.stillPhotos && selectedProject.stillPhotos.length > 0 ? (
                  selectedProject.stillPhotos.map((photo, i) => (
                    <div key={i} className="w-full bg-neutral-900 overflow-hidden shadow-2xl group border border-white/5">
                      <img 
                        src={formatImageUrl(photo)} 
                        className="w-full h-auto block transition-all duration-1000 group-hover:scale-[1.01]"
                        alt={`Scene Frame ${i + 1}`}
                      />
                    </div>
                  ))
                ) : (
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-12 opacity-10">
                     <div className="aspect-video bg-neutral-950 border border-white/5 flex items-center justify-center font-mono text-[9px] tracking-widest uppercase italic">Frame_Alpha</div>
                     <div className="aspect-video bg-neutral-950 border border-white/5 flex items-center justify-center font-mono text-[9px] tracking-widest uppercase italic">Frame_Beta</div>
                  </div>
                )}
              </div>
            </div>

            {/* 모달 하단 클로징 */}
            <div className="pt-64 pb-32 flex flex-col items-center justify-center">
               <button 
                  onClick={() => setSelectedProject(null)}
                  className="group flex flex-col items-center gap-6 text-neutral-700 hover:text-white transition-all duration-700"
               >
                  <div className="flex flex-col items-center gap-2">
                    <i className="fas fa-chevron-up text-[10px] group-hover:-translate-y-2 transition-transform"></i>
                    <i className="fas fa-chevron-up text-[8px] opacity-30 group-hover:-translate-y-2 transition-transform delay-75"></i>
                  </div>
                  <span className="text-[10px] uppercase tracking-[0.8em] font-bold">Back to Gallery</span>
               </button>
            </div>

          </div>
        </div>
      )}
    </div>
  );
};

export default ProjectList;

import React from 'react';
import { Link } from 'react-router-dom';
import { Project, DirectorInfo, ProjectCategory } from '../types';
import { formatImageUrl } from '../utils/imageHelper';

interface HomeProps {
  projects: Project[];
  director: DirectorInfo;
}

const Home: React.FC<HomeProps> = ({ projects, director }) => {
  const renderResumeCategory = (category: ProjectCategory, title: string) => {
    const filtered = projects.filter(p => p.category === category);

    const groupedByYear = filtered.reduce((acc: { [key: string]: Project[] }, project) => {
      if (!acc[project.year]) acc[project.year] = [];
      acc[project.year].push(project);
      return acc;
    }, {});

    const sortedYears = Object.keys(groupedByYear).sort((a, b) => b.localeCompare(a));

    if (filtered.length === 0) return null;

    return (
      <div key={category} className="mb-32 md:mb-40">
        <div className="mb-14 md:mb-20">
          <h3 className="text-xl md:text-2xl font-serif text-white tracking-[0.25em] uppercase mb-5">
            {title}
          </h3>
          <div className="h-px w-24 md:w-40 bg-neutral-800"></div>
        </div>

        <div className="space-y-16 md:space-y-24">
          {sortedYears.map((year) => (
            <div key={year} className="grid grid-cols-1 md:grid-cols-[140px_1fr] gap-6 md:gap-16">
              <div className="text-2xl md:text-3xl font-bold text-yellow-500 font-sans tracking-tight">
                {year}
              </div>

              <div className="space-y-14">
                {groupedByYear[year].map((project) => (
                  <div key={project.id} className="space-y-5">
                    <div className="flex flex-wrap items-baseline gap-x-3 text-lg md:text-xl">
                      <h4 className="font-bold tracking-tight text-white leading-tight break-keep">
                        {/* 영어 통일을 위해 단편/장편 레이블을 영어로 수정 */}
                        {project.isAI 
                          ? 'AI Short Film ' 
                          : project.isFeature 
                            ? 'Feature Film '
                            : (project.category === ProjectCategory.COMMERCIAL ? '' : 'Short Film ')
                        }
                        &lt;{project.title}&gt;
                      </h4>
                      <span className="text-neutral-500 font-medium text-base md:text-lg">
                        {project.role}
                      </span>
                    </div>

                    {project.awardsList && project.awardsList.length > 0 && (
                      <ul className="space-y-2.5">
                        {project.awardsList.map((award, idx) => (
                          <li key={idx} className="text-orange-400 text-[14px] md:text-[16px] font-normal leading-relaxed flex items-start gap-3">
                            <span className="text-orange-400/50 mt-1.5 text-[8px] flex-shrink-0">●</span>
                            <span className="flex-1 opacity-90">{award}</span>
                          </li>
                        ))}
                      </ul>
                    )}
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>
      </div>
    );
  };

  return (
    <div className="bg-black">
      {/* Hero Section */}
      <section className="relative h-screen w-full flex items-center justify-center overflow-hidden">
        <div className="absolute inset-0 z-0 bg-black">
          {/* Desktop/Tablet Background Image - Kept object-contain for full visibility */}
          <img 
            src={formatImageUrl("https://drive.google.com/file/d/1c4YXXdzakITg8GMGkBe7Y366LSCK2c3r/view?usp=sharing")} 
            alt="Hero Background Desktop" 
            className="hidden md:block w-full h-full object-contain opacity-80"
          />
          {/* Mobile Background Image - Reverted to object-cover with specific centering */}
          <img 
            src={formatImageUrl("https://drive.google.com/file/d/1_fdg9qMJjNKVYSf45J0umlAC4qJ5cYVO/view?usp=sharing")} 
            alt="Hero Background Mobile" 
            className="block md:hidden w-full h-full object-cover object-[33%_center] opacity-80"
          />
          <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-transparent to-black/60 pointer-events-none"></div>
        </div>

        <div className="relative z-10 text-center px-6 max-w-5xl">
          <p className="text-yellow-500 uppercase tracking-[0.6em] md:tracking-[0.8em] text-[10px] md:text-xs mb-8 md:mb-12 font-black drop-shadow-md">
            {director.title}
          </p>
          <h1 className="text-5xl sm:text-7xl md:text-8xl lg:text-[9rem] font-serif font-bold text-white mb-8 md:mb-10 tracking-tighter leading-[0.85] uppercase drop-shadow-[0_4px_12px_rgba(0,0,0,0.8)]">
            {director.nameEn.split(' ')[0]} <br /> {director.nameEn.split(' ')[1]}
          </h1>

          {/* New Navigation Buttons */}
          <div className="flex flex-wrap justify-center gap-4 mb-10 md:mb-14">
            <Link 
              to="/directing" 
              className="px-6 md:px-8 py-2.5 md:py-3 border border-white/30 bg-black/20 backdrop-blur-sm text-[10px] md:text-[11px] uppercase tracking-[0.3em] font-bold text-white hover:bg-white hover:text-black transition-all duration-300"
            >
              FILM PORTFOLIO
            </Link>
            <Link 
              to="/commercial" 
              className="px-6 md:px-8 py-2.5 md:py-3 border border-white/30 bg-black/20 backdrop-blur-sm text-[10px] md:text-[11px] uppercase tracking-[0.3em] font-bold text-white hover:bg-white hover:text-black transition-all duration-300"
            >
              COMMERCIAL PORTFOLIO
            </Link>
          </div>

          <div className="flex items-center justify-center gap-6 md:gap-10">
            <span className="h-px w-12 md:w-24 bg-white/40"></span>
            <p className="text-white text-[10px] md:text-xs tracking-[0.5em] md:tracking-[0.7em] uppercase font-bold whitespace-nowrap drop-shadow-lg">Visual Storyteller</p>
            <span className="h-px w-12 md:w-24 bg-white/40"></span>
          </div>
        </div>

        <div className="absolute bottom-10 left-1/2 -translate-x-1/2 animate-bounce cursor-pointer opacity-50 hover:opacity-100 transition-opacity" onClick={() => document.getElementById('about')?.scrollIntoView({ behavior: 'smooth' })}>
          <i className="fas fa-chevron-down text-white text-xl"></i>
        </div>
      </section>

      {/* About Section */}
      <section id="about" className="py-24 md:py-48 px-6 bg-neutral-950/50 border-t border-white/5">
        <div className="max-w-7xl mx-auto">
          <div className="flex flex-col lg:flex-row items-center gap-16 lg:gap-32">
            <div className="relative flex-shrink-0 group">
              <div className="w-56 h-56 md:w-80 md:h-80 rounded-full overflow-hidden border border-white/10 p-2 transition-all duration-700 group-hover:border-yellow-500/40">
                <img 
                  src={formatImageUrl(director.profileImageUrl)} 
                  alt={director.name} 
                  className="w-full h-full object-cover rounded-full grayscale group-hover:grayscale-0 transition-all duration-1000"
                />
              </div>
              <div className="absolute -bottom-1 -right-1 bg-yellow-500 text-black px-6 py-2.5 rounded-full text-[10px] font-black uppercase tracking-widest shadow-2xl">
                Director
              </div>
            </div>

            <div className="flex-grow space-y-10 md:space-y-12 text-center lg:text-left">
              <div className="space-y-6">
                <h2 className="text-[10px] md:text-xs uppercase tracking-[0.5em] md:tracking-[0.7em] text-yellow-500 font-black opacity-80">Introduction</h2>
                <h3 className="text-4xl sm:text-5xl md:text-7xl font-serif text-white leading-tight">
                  {director.name} <br /><span className="text-neutral-600 italic text-2xl md:text-5xl">{director.nameEn}</span>
                </h3>
                <p className="text-base md:text-xl text-neutral-400 leading-relaxed font-light max-w-3xl mx-auto lg:mx-0">
                  {director.bio}
                </p>
              </div>

              <div className="pt-10 md:pt-14 border-t border-white/5 flex flex-col md:flex-row items-center lg:items-start gap-12 md:gap-20">
                <div className="space-y-2 text-left">
                    <span className="text-[9px] md:text-[10px] uppercase text-neutral-600 tracking-widest font-bold block mb-1">Contact</span>
                    <a href={`tel:${director.phone}`} className="text-white hover:text-yellow-500 transition-colors text-2xl md:text-3xl font-serif block tracking-tight">{director.phone}</a>
                    <a href={`mailto:${director.email}`} className="text-neutral-500 hover:text-yellow-500 transition-colors text-sm md:text-lg block">{director.email}</a>
                </div>
                <div className="flex items-center gap-8">
                  <a href={director.instagram} target="_blank" rel="noreferrer" className="w-14 h-14 md:w-16 md:h-16 flex items-center justify-center rounded-full border border-white/10 text-neutral-500 hover:text-white hover:border-yellow-500 transition-all bg-white/5">
                    <i className="fab fa-instagram text-2xl"></i>
                  </a>
                  <a href={director.youtube} target="_blank" rel="noreferrer" className="w-14 h-14 md:w-16 md:h-16 flex items-center justify-center rounded-full border border-white/10 text-neutral-500 hover:text-white hover:border-yellow-500 transition-all bg-white/5">
                    <i className="fab fa-youtube text-2xl"></i>
                  </a>
                </div>
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* CV Section */}
      <section id="filmography" className="py-24 md:py-48 px-6 max-w-6xl mx-auto border-t border-white/5">
        <header className="mb-24 md:mb-40 text-center space-y-6 md:space-y-10">
            <h2 className="text-5xl sm:text-6xl md:text-8xl font-serif text-white tracking-[0.1em] md:tracking-widest leading-none">
              CURRICULUM VITAE
            </h2>
            <div className="text-neutral-500 text-[10px] md:text-[13px] uppercase tracking-[0.5em] md:tracking-[0.9em] font-medium opacity-60">
              FILMOGRAPHY & PROFESSIONAL EXPERIENCE
            </div>
        </header>

        <div className="flex flex-col">
          {/* 순서 조정: DIRECTING -> COMMERCIAL WORKS -> CINEMATOGRAPHY -> AD & PRODUCING */}
          {renderResumeCategory(ProjectCategory.DIRECTING, "Directing")}
          {renderResumeCategory(ProjectCategory.COMMERCIAL, "Commercial Works")}
          {renderResumeCategory(ProjectCategory.CINEMATOGRAPHY, "Cinematography")}
          {renderResumeCategory(ProjectCategory.PRODUCING, "AD & Producing")}
        </div>

        <div className="mt-32 md:mt-48 text-center border-t border-white/5 pt-20 md:pt-32">
            <p className="text-neutral-600 text-[10px] md:text-[12px] uppercase tracking-[0.6em] md:tracking-[0.8em] mb-12 md:mb-20 italic opacity-50">
              Continuing the visual journey
            </p>
            <div className="flex flex-wrap justify-center gap-8 md:gap-20">
              <a href={director.adPortfolio} target="_blank" rel="noreferrer" className="group flex items-center gap-4 text-yellow-600 text-[10px] md:text-[12px] uppercase tracking-[0.4em] font-bold hover:text-white transition-all">
                <span>Advertising Portfolio</span>
                <i className="fas fa-arrow-right text-[10px] transform group-hover:translate-x-1.5 transition-transform"></i>
              </a>
              <a href={director.youtube} target="_blank" rel="noreferrer" className="group flex items-center gap-4 text-yellow-600 text-[10px] md:text-[12px] uppercase tracking-[0.4em] font-bold hover:text-white transition-all">
                <span>Personal Channel</span>
                <i className="fas fa-arrow-right text-[10px] transform group-hover:translate-x-1.5 transition-transform"></i>
              </a>
            </div>
        </div>
      </section>
    </div>
  );
};

export default Home;

import React, { useState } from 'react';
import { Project, ProjectCategory } from '../types';
import { DIRECTOR_INFO } from '../data';
import { formatImageUrl } from '../utils/imageHelper';

interface ProjectListProps {
  category: ProjectCategory;
  projects: Project[];
}

const ProjectList: React.FC<ProjectListProps> = ({ category, projects }) => {
  const [selectedProject, setSelectedProject] = useState<Project | null>(null);
  const filteredProjects = projects.filter(p => p.category === category);

  // 데이터에 정의된 순서 그대로 유지
  const displayProjects = filteredProjects; 

  const isCommercial = category === ProjectCategory.COMMERCIAL;
  const isProducing = category === ProjectCategory.PRODUCING;

  // 첫 글자만 대문자, 나머지는 소문자로 변환하는 헬퍼 함수
  const formatText = (str: string | undefined) => {
    if (!str) return '';
    return str.charAt(0).toUpperCase() + str.slice(1).toLowerCase();
  };

  const handleProjectClick = (project: Project) => {
    if (isCommercial) {
      window.open(project.link || DIRECTOR_INFO.adPortfolio, '_blank');
    } else {
      setSelectedProject(project);
    }
  };

  return (
    <div className="pt-24 md:pt-32 min-h-screen bg-black text-neutral-300 overflow-x-hidden">
      <div className="max-w-7xl mx-auto px-6 py-12 md:py-20">
        <header className="mb-24 md:mb-40 text-center">
          <h1 className="text-4xl sm:text-6xl md:text-8xl font-serif text-white tracking-[0.1em] md:tracking-[0.2em] uppercase mb-4 leading-tight">
            {category}
          </h1>
          <div className="w-16 md:w-24 h-px bg-white/20 mx-auto mt-6 md:mt-10"></div>
        </header>

        <div className="space-y-40 md:space-y-64">
          {displayProjects.map((project, index) => {
            const isEven = index % 2 === 0;
            const hasPoster = !isProducing && project.posterUrl;

            return (
              <div 
                key={project.id} 
                className={`flex flex-col ${isEven ? 'md:flex-row' : 'md:flex-row-reverse'} items-center gap-10 md:gap-24`}
              >
                {/* 리스트 프리뷰 섹션 (포스터) */}
                <div 
                  className="w-full md:w-1/2 relative group cursor-pointer"
                  onClick={() => handleProjectClick(project)}
                >
                  <div className="aspect-[3/4.5] overflow-hidden bg-neutral-900 shadow-[0_0_50px_rgba(0,0,0,0.8)] border border-white/5 relative flex items-center justify-center">
                    {hasPoster ? (
                      <img 
                        src={formatImageUrl(project.posterUrl!)} 
                        alt={project.title}
                        className="w-full h-full object-cover transition-all duration-1000 group-hover:scale-105 opacity-80 group-hover:opacity-100"
                      />
                    ) : (
                      <div className="text-neutral-800 font-serif italic text-sm md:text-lg tracking-widest opacity-40 select-none">
                        NO POSTER AVAILABLE
                      </div>
                    )}

                    {project.isAI && (
                      <div className="absolute top-4 right-4 z-10">
                        <div className="bg-black/60 backdrop-blur-md border border-yellow-500/50 px-3 py-1 text-[9px] font-black tracking-[0.2em] text-yellow-500 uppercase rounded-sm shadow-xl">
                          AI FILM
                        </div>
                      </div>
                    )}

                    <div className="absolute inset-0 bg-black/20 group-hover:bg-transparent transition-all duration-500"></div>

                    <div className="absolute inset-0 flex items-center justify-center opacity-100 md:opacity-0 md:group-hover:opacity-100 transition-opacity duration-500">
                      <div className="border border-white bg-black/40 backdrop-blur-md px-6 md:px-8 py-3 text-[9px] md:text-[10px] uppercase tracking-[0.2em] md:tracking-[0.3em] font-bold text-white group-hover:bg-white group-hover:text-black transition-all flex items-center justify-center">
                        자세히 보기 {isCommercial && <i className="fab fa-youtube ml-3 text-red-500"></i>}
                      </div>
                    </div>
                  </div>
                </div>

                {/* 리스트 텍스트 섹션 (제목) */}
                <div className="w-full md:w-1/2 space-y-6 md:space-y-8 text-left">
                  <div className="space-y-3 md:space-y-4">
                    <span className="text-yellow-600 font-bold tracking-widest text-xs md:text-sm block">
                      {project.year}
                    </span>
                    <h2 
                      className="text-3xl md:text-5xl font-serif text-white leading-tight tracking-tight break-keep cursor-pointer hover:text-yellow-500 transition-colors"
                      onClick={() => handleProjectClick(project)}
                    >
                      {project.title} {project.titleEn && <span className="text-neutral-500 text-xl md:text-3xl block md:inline md:ml-2">({project.titleEn})</span>}
                    </h2>

                    {(project.genre || project.runtime || project.aspectRatio) && (
                      <div className="flex flex-wrap gap-3 md:gap-4 text-orange-400 font-bold text-[10px] md:text-xs tracking-widest pt-1 md:pt-2">
                        {project.genre && <span>{formatText(project.genre)}</span>}
                        {project.runtime && <span className="text-neutral-800">|</span>}
                        {project.runtime && <span>{formatText(project.runtime)}</span>}
                        {project.aspectRatio && <span className="text-neutral-800">|</span>}
                        {project.aspectRatio && <span>{project.aspectRatio}</span>}
                      </div>
                    )}
                  </div>

                  {!isCommercial && (
                    <p className="text-neutral-400 leading-relaxed font-light text-base md:text-lg max-w-lg">
                      {project.synopsis ? project.synopsis.slice(0, 150) + '...' : project.description || "상세 정보가 준비 중입니다."}
                    </p>
                  )}

                  {project.awardsList && project.awardsList.length > 0 && (
                    <div className="space-y-2 md:space-y-3 pt-2 md:pt-4">
                      {project.awardsList.slice(0, 5).map((award, i) => (
                        <div key={i} className="flex items-start gap-3 text-orange-400 text-xs md:text-sm font-medium leading-snug">
                          <i className="fas fa-award text-[10px] text-orange-400/70 mt-1"></i>
                          <span>{award}</span>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* 영화 상세 정보 모달 */}
      {!isCommercial && selectedProject && (
        <div className="fixed inset-0 z-[100] bg-black overflow-y-auto custom-scrollbar flex flex-col items-center">
          {/* 닫기 버튼 */}
          <button 
            className="fixed top-8 right-8 md:top-12 md:right-12 z-[120] text-neutral-700 hover:text-white transition-all p-3 group" 
            onClick={() => setSelectedProject(null)}
          >
            <i className="fas fa-times text-2xl group-hover:rotate-90 transition-transform duration-300"></i>
          </button>

          {/* 메인 콘텐츠 컨테이너: 중앙 정렬 */}
          <div className="w-full max-w-7xl px-6 md:px-12 pt-24 md:pt-48 pb-24 mx-auto">

            {/* 상단 섹션: 포스터(Sticky) + 정보(Scroll) */}
            <div className="flex flex-col lg:flex-row gap-16 lg:gap-32 mb-48 relative items-start justify-center">

              {/* 좌측: 포스터 & 스펙 (스티키) */}
              <div className="w-full lg:w-[400px] flex-shrink-0 lg:sticky lg:top-32 h-fit space-y-10">
                <div className="aspect-[3/4.2] overflow-hidden bg-neutral-950 border border-white/5 shadow-2xl relative">
                  {selectedProject.posterUrl ? (
                    <img 
                      src={formatImageUrl(selectedProject.posterUrl)} 
                      className="w-full h-full object-cover"
                      alt={selectedProject.title}
                    />
                  ) : (
                    <div className="w-full h-full flex items-center justify-center text-neutral-800 text-[10px] tracking-[0.5em] uppercase italic opacity-30">Cinematic Archive</div>
                  )}
                </div>

                {/* 하단 스펙 테이블 */}
                <div className="border-t border-white/10">
                  {[
                    { label: 'Year', value: selectedProject.year },
                    { label: 'Genre', value: formatText(selectedProject.genre) || 'Drama' },
                    { label: 'Runtime', value: formatText(selectedProject.runtime) || 'N/a' },
                    { label: 'Role', value: selectedProject.role }
                  ].map((item, idx) => (
                    <div key={idx} className="flex justify-between items-center py-4 border-b border-white/5">
                      <span className="text-[9px] uppercase tracking-[0.2em] text-neutral-500 font-bold">{item.label}</span>
                      <span className="text-[12px] font-bold text-neutral-200 tracking-tight">{item.value}</span>
                    </div>
                  ))}
                </div>
              </div>

              {/* 우측: 텍스트 정보 */}
              <div className="flex-grow space-y-24 max-w-2xl">
                {/* 1. 타이틀 영역 */}
                <div className="space-y-4">
                  <h2 className="text-4xl md:text-5xl lg:text-7xl font-serif text-white tracking-tight leading-[1.1] uppercase break-keep">
                    {selectedProject.title}
                  </h2>
                  {selectedProject.titleEn && (
                    <p className="text-neutral-500 font-serif text-xl md:text-2xl italic opacity-40">
                      {selectedProject.titleEn}
                    </p>
                  )}
                </div>

                {/* 2. 시놉시스: 줄 간격(1.8) 유지하되 글자 크기(15px/17px) 하향 조정 */}
                <div className="space-y-8">
                  <div className="flex items-center gap-6">
                    <div className="w-10 h-px bg-yellow-600/40"></div>
                    <h3 className="text-[10px] uppercase tracking-[0.5em] text-yellow-600 font-black">Synopsis</h3>
                  </div>
                  <p className="text-neutral-300 text-[15px] md:text-[17px] leading-[1.8] tracking-normal font-normal break-keep whitespace-pre-line opacity-90">
                    {selectedProject.synopsis || "작품의 기록이 준비 중입니다."}
                  </p>
                </div>

                {/* 2.5. 기획의도 (Planning Intention): description 필드가 있는 경우 표시 */}
                {selectedProject.description && (
                  <div className="space-y-8">
                    <div className="flex items-center gap-6">
                      <div className="w-10 h-px bg-yellow-600/40"></div>
                      <h3 className="text-[10px] uppercase tracking-[0.5em] text-yellow-600 font-black">Planning Intention</h3>
                    </div>
                    <p className="text-white text-[15px] md:text-[17px] font-serif italic leading-[1.8] tracking-tight break-keep whitespace-pre-line opacity-100">
                      {selectedProject.description}
                    </p>
                  </div>
                )}

                {/* 3. 수상 내역 (Recognition) */}
                {selectedProject.awardsList && selectedProject.awardsList.length > 0 && (
                  <div className="space-y-10">
                    <div className="flex items-center gap-6">
                      <div className="w-10 h-px bg-yellow-600/40"></div>
                      <h3 className="text-[10px] uppercase tracking-[0.5em] text-yellow-600 font-black">Recognition</h3>
                    </div>
                    <ul className="space-y-5">
                      {selectedProject.awardsList.map((award, i) => (
                        <li key={i} className="flex items-start gap-5 text-orange-400 text-base md:text-lg font-light group">
                          <span className="w-1.5 h-1.5 rounded-full bg-orange-400/30 mt-2.5 group-hover:bg-orange-400 transition-colors"></span>
                          <span className="group-hover:text-orange-400 transition-colors duration-300 leading-snug">{award}</span>
                        </li>
                      ))}
                    </ul>
                  </div>
                )}
              </div>
            </div>

            {/* 하단 섹션: 스틸컷 */}
            <div className="space-y-16 border-t border-white/5 pt-40">
              <div className="flex flex-col items-center gap-10 mb-16">
                 <h3 className="text-[10px] uppercase tracking-[1em] text-neutral-700 font-black">Cinematic Frames</h3>
                 <div className="w-px h-24 bg-gradient-to-b from-white/10 to-transparent"></div>
              </div>

              <div className="space-y-16 md:space-y-32">
                {selectedProject.stillPhotos && selectedProject.stillPhotos.length > 0 ? (
                  selectedProject.stillPhotos.map((photo, i) => (
                    <div key={i} className="w-full bg-neutral-900 overflow-hidden shadow-2xl group border border-white/5">
                      <img 
                        src={formatImageUrl(photo)} 
                        className="w-full h-auto block transition-all duration-1000 group-hover:scale-[1.01]"
                        alt={`Scene Frame ${i + 1}`}
                      />
                    </div>
                  ))
                ) : (
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-12 opacity-10">
                     <div className="aspect-video bg-neutral-950 border border-white/5 flex items-center justify-center font-mono text-[9px] tracking-widest uppercase italic">Frame_Alpha</div>
                     <div className="aspect-video bg-neutral-950 border border-white/5 flex items-center justify-center font-mono text-[9px] tracking-widest uppercase italic">Frame_Beta</div>
                  </div>
                )}
              </div>
            </div>

            {/* 모달 하단 클로징 */}
            <div className="pt-64 pb-32 flex flex-col items-center justify-center">
               <button 
                  onClick={() => setSelectedProject(null)}
                  className="group flex flex-col items-center gap-6 text-neutral-700 hover:text-white transition-all duration-700"
               >
                  <div className="flex flex-col items-center gap-2">
                    <i className="fas fa-chevron-up text-[10px] group-hover:-translate-y-2 transition-transform"></i>
                    <i className="fas fa-chevron-up text-[8px] opacity-30 group-hover:-translate-y-2 transition-transform delay-75"></i>
                  </div>
                  <span className="text-[10px] uppercase tracking-[0.8em] font-bold">Back to Gallery</span>
               </button>
            </div>

          </div>
        </div>
      )}
    </div>
  );
};

